// bg.cpp — exact-rational (and fast double) Berends-Giele oracle for 1D
// water-wave amplitudes. Faithful transcription of OnShellBG.m
// (EKernel/FKernel/Vertex/Propagator/SetPartitions/BGCurrent/BGAmplitude/
// MakeKinematics). The engine is templated on the real scalar type, so the
// exact (GMP mpq_class) and fast (long double) paths run the SAME algorithm.
// It is a pure amplitude evaluator — it contains no closed-form/answer.
//
// Build: g++ -O2 -std=c++17 -o bg bg.cpp -lgmpxx -lgmp
// Use:
//   ./bg -n 5 -w 2,3,5 -s -1,-1,-1,1,1 [-g 1]      # on-shell, exact rational
//   ./bg --amp -K <n momenta> -W <n omegas> [-g 1] # raw BGAmplitude, exact
//   ./bg --double -n 8 -w 1,2,3,4,5,6 -s -1,-1,-1,1,1,1,1,1   # fast double mode
// Frequencies/momenta are real; the imaginary unit enters only via (-i/2) in
// Vertex and (-i) in Propagator, so amplitudes are (a+bi) with a,b in the field.
#include <bits/stdc++.h>
#include <gmpxx.h>
using namespace std;

// --- abs for each scalar (ADL/overload) ---
static inline mpq_class absR(const mpq_class& x){ return abs(x); }
static inline long double absR(long double x){ return fabsl(x); }

// --- scalar parse ("5/2", "-3", "0.1") ---
template<class R> R parse1(const string& t);
template<> mpq_class parse1<mpq_class>(const string& t){ mpq_class q(t); q.canonicalize(); return q; }
template<> long double parse1<long double>(const string& t){
  size_t p=t.find('/');
  if(p==string::npos) return strtold(t.c_str(), nullptr);
  return strtold(t.substr(0,p).c_str(), nullptr)/strtold(t.substr(p+1).c_str(), nullptr);
}
template<class R> vector<R> parseList(const string& s){
  vector<R> v; if(s.empty()) return v; stringstream ss(s); string t;
  while(getline(ss,t,',')) if(!t.empty()) v.push_back(parse1<R>(t));
  return v;
}

// --- memo-key serialization of a scalar ---
static inline string sval(const mpq_class& x){ return x.get_str(); }
static inline string sval(long double x){ char b[48]; snprintf(b,sizeof b,"%.20Lg",x); return b; }

// --- set partitions of S into exactly k blocks (index-only; scalar-independent) ---
static vector<vector<vector<int>>> SetPartitions(const vector<int>& S, int k){
  if(k==1) return {{S}};
  if(k>(int)S.size()) return {};
  int mn=*min_element(S.begin(),S.end());
  vector<int> X; for(int x:S) if(x!=mn) X.push_back(x);
  int L=(int)S.size(), xs=(int)X.size();
  vector<vector<vector<int>>> out;
  for(int mask=0; mask<(1<<xs); ++mask){
    if(__builtin_popcount(mask) > L-k) continue;
    set<int> fps{mn}; vector<int> fp{mn};
    for(int b=0;b<xs;b++) if(mask&(1<<b)){ fp.push_back(X[b]); fps.insert(X[b]); }
    sort(fp.begin(),fp.end());
    vector<int> rem; for(int v:S) if(!fps.count(v)) rem.push_back(v);
    if((int)rem.size()>=k-1)
      for(auto& sp:SetPartitions(rem,k-1)){ vector<vector<int>> b{fp}; for(auto& x:sp) b.push_back(x); out.push_back(b); }
  }
  return out;
}

template<class R>
struct Engine {
  struct Cx { R re, im; };
  static Cx cadd(const Cx&a,const Cx&b){ return {a.re+b.re, a.im+b.im}; }
  static Cx cmul(const Cx&a,const Cx&b){ return {a.re*b.re-a.im*b.im, a.re*b.im+a.im*b.re}; }

  vector<R> K, W; R G{1};                     // 1-indexed: K[1..N], W[1..N]
  unordered_map<string,R> Em, Fm;
  unordered_map<unsigned long long,Cx> BGm;

  R fact(int k){ R r(1); for(int i=2;i<=k;i++) r=r*R(i); return r; }
  R powi(const R&b,int e){ R r(1); for(int i=0;i<e;i++) r=r*b; return r; }
  string keyOf(int n,const vector<R>&ps){ string s=to_string(n); for(auto&p:ps){ s.push_back('|'); s+=sval(p);} return s; }

  R EKernel(int n,const vector<R>&ps){
    if(n==3) return (R(-1)/R(2))*(absR(ps[0])*absR(ps[1]) + ps[0]*ps[1]);
    string key=keyOf(n,ps); auto it=Em.find(key); if(it!=Em.end()) return it->second;
    R p1=ps[0], p2=ps[1]; vector<R> rest(ps.begin()+2, ps.end());
    R qp2=absR(p2), rs(0); for(auto&r:rest) rs=rs+r;
    R res = powi(qp2,n-3)*EKernel(3,{p1,p2,rs})/fact(n-2);
    for(int m=1;m<=n-3;m++){
      R part(0); for(int j=0;j<m;j++) part=part+rest[j];
      vector<R> nl{p1, p2+part}; for(size_t j=m;j<rest.size();j++) nl.push_back(rest[j]);
      res = res - powi(qp2,m)/fact(m)*EKernel(n-m,nl);
    }
    Em[key]=res; return res;
  }
  R FKernel(int n,const vector<R>&ps){
    if(n==3) return R(-1) - ps[0]*ps[1]/(absR(ps[0])*absR(ps[1]));
    string key=keyOf(n,ps); auto it=Fm.find(key); if(it!=Fm.end()) return it->second;
    R p1=ps[0], p2=ps[1]; vector<R> rest(ps.begin()+2, ps.end());
    R qp1=absR(p1), qp2=absR(p2);
    R res = R(2)*EKernel(n,ps)/qp1;
    for(int m=1;m<=n-3;m++){
      R part(0); for(int j=0;j<m;j++) part=part+rest[j];
      R sigM=p2+part;
      vector<R> el{-sigM, p2}; for(int j=0;j<m;j++) el.push_back(rest[j]);
      vector<R> fl{p1, sigM};  for(size_t j=m;j<rest.size();j++) fl.push_back(rest[j]);
      res = res - R(2)*EKernel(m+2,el)*FKernel(n-m,fl);
    }
    res = res/qp2; Fm[key]=res; return res;
  }
  Cx Vertex(int n,const vector<R>&moms,const vector<R>&om){
    vector<int> p(n); iota(p.begin(),p.end(),0); R acc(0); vector<R> pm(n);
    do { for(int i=0;i<n;i++) pm[i]=moms[p[i]]; acc = acc + om[p[0]]*om[p[1]]*FKernel(n,pm); }
    while(next_permutation(p.begin(),p.end()));
    return Cx{R(0), -acc/R(2)};               // (-i/2)*acc
  }
  Cx Propagator(const R&wS,const R&kS){ R D = wS*wS/absR(kS) - G; return Cx{R(0), R(-1)/D}; }

  Cx BGCurrent(const vector<int>&S){
    if(S.size()==1) return Cx{R(1),R(0)};
    unsigned long long mask=0; for(int i:S) mask|=(1ULL<<i);
    auto it=BGm.find(mask); if(it!=BGm.end()) return it->second;
    R wS(0),kS(0); for(int i:S){ wS=wS+W[i]; kS=kS+K[i]; }
    Cx result{R(0),R(0)};
    for(int m=2;m<=(int)S.size();m++)
      for(auto& part:SetPartitions(S,m)){
        vector<R> vM{-kS}, vO{-wS};
        for(auto& blk:part){ R km(0),om(0); for(int i:blk){ km=km+K[i]; om=om+W[i]; } vM.push_back(km); vO.push_back(om); }
        Cx v=Vertex(m+1,vM,vO), prod{R(1),R(0)};
        for(auto& blk:part) prod=cmul(prod,BGCurrent(blk));
        result=cadd(result,cmul(v,prod));
      }
    result=cmul(result,Propagator(wS,kS)); BGm[mask]=result; return result;
  }
  Cx BGAmplitude(int N){
    BGm.clear(); Em.clear(); Fm.clear();
    vector<int> rest; for(int i=2;i<=N;i++) rest.push_back(i);
    Cx result{R(0),R(0)};
    for(int m=2;m<=N-1;m++)
      for(auto& part:SetPartitions(rest,m)){
        vector<R> vM{K[1]}, vO{W[1]};
        for(auto& blk:part){ R km(0),om(0); for(int i:blk){ km=km+K[i]; om=om+W[i]; } vM.push_back(km); vO.push_back(om); }
        Cx v=Vertex(m+1,vM,vO), prod{R(1),R(0)};
        for(auto& blk:part) prod=cmul(prod,BGCurrent(blk));
        result=cadd(result,cmul(v,prod));
      }
    return result;
  }
};

template<class R>
int runMode(bool rawAmp,int N,const string&ws,const string&ss,const string&ks,const string&Ws,const string&gs){
  Engine<R> E; E.G = parse1<R>(gs);
  if(rawAmp){
    auto kk=parseList<R>(ks), wwv=parseList<R>(Ws);
    if(kk.empty() || kk.size()!=wwv.size()){ cerr<<"--amp needs -K and -W of equal length n\n"; return 1; }
    N=(int)kk.size(); E.K.assign(N+1,R(0)); E.W.assign(N+1,R(0));
    for(int i=1;i<=N;i++){ E.K[i]=kk[i-1]; E.W[i]=wwv[i-1]; }
  } else {
    auto freeW=parseList<R>(ws), sig=parseList<R>(ss);
    if((int)freeW.size()!=N-2 || (int)sig.size()!=N){ cerr<<"usage: -n N -w <n-2 free freqs> -s <n signs> [-g 1] | --amp -K <n moms> -W <n omegas>\n"; return 1; }
    if(!(sig[0]+sig[N-1]==R(0))){ cerr<<"need sigma_1 + sigma_n = 0\n"; return 1; }
    R sumFree(0); for(auto&x:freeW) sumFree=sumFree+x;
    R sumSig(0); for(int i=0;i<N-2;i++) sumSig = sumSig + sig[i+1]*freeW[i]*freeW[i];
    R wn = -(sig[0]*sumFree*sumFree + sumSig)/(R(2)*sig[0]*sumFree);
    R w1 = -(sumFree+wn);
    E.W.assign(N+1,R(0)); E.K.assign(N+1,R(0));
    E.W[1]=w1; for(int i=0;i<N-2;i++) E.W[i+2]=freeW[i]; E.W[N]=wn;
    for(int i=1;i<=N;i++) E.K[i]=sig[i-1]*E.W[i]*E.W[i]/E.G;
  }
  auto A=E.BGAmplitude(N);
  cout<<"n = "<<N<<"\n";
  if constexpr(is_same_v<R,mpq_class>){
    A.re.canonicalize(); A.im.canonicalize();
    cout<<"omega = {"; for(int i=1;i<=N;i++) cout<<E.W[i].get_str()<<(i<N?", ":"}\n");
    if(A.re==0) cout<<"A_"<<N<<" = i * ("<<A.im.get_str()<<")\n";
    else        cout<<"A_"<<N<<" = ("<<A.re.get_str()<<") + i * ("<<A.im.get_str()<<")\n";
    cout<<"A_"<<N<<" (numeric) = "<<mpf_class(A.re,256).get_d()<<" + "<<mpf_class(A.im,256).get_d()<<" i\n";
  } else {
    cout<<setprecision(15);
    cout<<"omega = {"; for(int i=1;i<=N;i++) cout<<(double)E.W[i]<<(i<N?", ":"}\n");
    cout<<"A_"<<N<<" (double) = "<<(double)A.re<<" + "<<(double)A.im<<" i\n";
  }
  return 0;
}

int main(int argc,char**argv){
  string ws, ss, ks, Ws, gs="1"; bool rawAmp=false, useDouble=false; int N=0;
  for(int i=1;i<argc;i++){ string a=argv[i];
    if(a=="--amp") rawAmp=true;
    else if(a=="--double") useDouble=true;
    else if(a=="-n") N=atoi(argv[++i]);
    else if(a=="-w") ws=argv[++i];
    else if(a=="-s") ss=argv[++i];
    else if(a=="-K") ks=argv[++i];
    else if(a=="-W") Ws=argv[++i];
    else if(a=="-g") gs=argv[++i];
  }
  return useDouble ? runMode<long double>(rawAmp,N,ws,ss,ks,Ws,gs)
                   : runMode<mpq_class>(rawAmp,N,ws,ss,ks,Ws,gs);
}
# A6 local pipeline (student-1)

This directory contains the corrected stage scripts for pole approach, wall approach, and final ansatz fitting.

## Run commands
- Compile all scripts:
  - `python3 -m py_compile bots/student-1/code/calibration.py bots/student-1/code/domain_scan.py bots/student-1/code/pole_scan.py bots/student-1/code/wall_approach.py bots/student-1/code/ansatz_fit.py bots/student-1/code/common.py bots/student-1/code/exact_oracle.py`
- Run the full pipeline:
  - `bash bots/student-1/code/run_pipeline.sh`

## Orchestrated pipeline
`run_pipeline.sh` runs, in order:
1. `calibration.py`
2. `domain_scan.py`
3. `pole_scan.py`
4. `wall_approach.py`
5. `ansatz_fit.py`

Each script writes to `bots/student-1/data/*` and logs to `bots/student-1/data/*.log`.

## Pole scan strategy (`pole_scan.py`)
- Uses orbit decomposition of internal subsets under `S3 x S3` and set-swap.
- Supported compositions: `(2,0)`, `(1,1)`, `(3,0)`, `(2,1)` (with size-pair normalized by swap).
- `(2,0)` and `(1,1)` are recorded as algebraically degenerate and are **not** numerically scanned.
- For `(3,0)` and `(2,1)`, each affine family is:
  - `(w2,w3,w4,w5) = c + d*t` with 12 deterministic rational `(c,d)` pairs (see script constant `FAMILIES`).
- Pole condition uses exact finite-difference sign branch:
  - `h = (sum_T w)^2 - sign(q_T) * q_T`.
- Root scans are done by SymPy exact rational expressions (`factor/nroots` on cleared-denominator polynomials), with root centers stored at 14-decimal rational form.
- Side probes are at `t_c ± 10^{-d}` for `d=2..7`, exact (`common.solve_from_free` + `exact_oracle.evaluate_omega`).
- Rejection checks include nonzero free sum, nonzero `q`, no zero `w_i`, no wall zero in the 18 nondegenerate walls, and no inequivalent triple-pole `h=0`.
- Outputs:
  - `data/pole_approaches.json`
  - `data/pole_report.txt`

## Wall scan strategy (`wall_approach.py`)
- Targets nondegenerate wall composition orbits `(1,1)` and `(1,2)`.
- Uses the same 12 affine rational families and SymPy exact rational scanning.
- Rejections include free-sum/kinematic validity, external wall zeros, non-target wall zeros among 18 wall formulas, and other triple-pole `h=0`.
- Side probes: `t_c ± 10^{-d}` for `d=2..7`, exact BG evaluation.
- Requires both-side `|q|` decade scaling to pass for coverage classification.
- Outputs:
  - `data/wall_approaches.json`
  - `data/wall_report.txt`

## ansatz fit (`ansatz_fit.py`)
- Uses category features `r1_*` and `r2_*` with no `_Ixx` suffix.
- Uses `CategoryFeature(r, category)` and `CategoryFeature._b` with positive-part cube, alternating finite-difference signs.
- Keeps full subset-loop over `I` and per-feature invariance checks.

## H1 feature definition/counts
- Features are named by category pairs in
  - `r1_A_A_diag`, `r1_A_C`, `r1_A_R`, `r1_C_C_diag`, `r1_C_C_off`, `r1_C_R`, `r1_R_R_diag`, `r1_R_R_off`
  - `r2_A_A_diag`, `r2_A_A_off`, `r2_A_C`, `r2_A_R`, `r2_C_C_diag`, `r2_C_R`, `r2_R_R_diag`, `r2_R_R_off`
- Total counts in this script: `r1=8`, `r1+r2=16`.

## Dependencies and runtime
- Python 3.6+
- GMP-backed `bg` binary built by `run_pipeline.sh`
- `sympy` (exact rational root handling for pole/wall scans)
- Standard library modules used in these scripts.

## Known outputs in `bots/student-1/data`
- `calibration.txt`
- `domain_scan.log`, `domain_scan.json`/`domain_signatures.json`
- `wall_catalog.json`
- `pole_approaches.json`, `pole_report.txt`, `pole_scan.log`
- `wall_approaches.json`, `wall_report.txt`, `wall_approach.log`
- `h1_fit_report.json`, `h1_fit_report.txt`
from fractions import Fraction
from itertools import combinations, permutations
from pathlib import Path

ROOT = Path(__file__).resolve().parent
BG_BIN = ROOT / "bg"

SIG_M = [-1, -1, -1]
SIG_P = [1, 1, 1]
SIG_FULL = [-1, -1, -1, 1, 1, 1]


# ---------- generic utilities ----------


def parse_fraction(text):
    text = str(text).strip()
    if text == "" or text.lower() == "nan":
        raise ValueError("empty fraction")
    return Fraction(text)


def frac_to_str(x: Fraction) -> str:
    return str(x.numerator) if x.denominator == 1 else "%s/%s" % (x.numerator, x.denominator)


def iter_subsets(n, min_size=1, max_size=None):
    if max_size is None:
        max_size = n
    out = []
    for r in range(min_size, max_size + 1):
        for idxs in combinations(range(n), r):
            out.append(bits_to_mask(idxs))
    return out


def subset_bits(mask):
    out = []
    p = 0
    while mask:
        if mask & 1:
            out.append(p)
        mask >>= 1
        p += 1
    return out


def bits_to_mask(idxs):
    m = 0
    for i in idxs:
        m |= 1 << i
    return m


def solve_from_free(omega2_omega5, signs):
    if len(omega2_omega5) + 2 != len(signs):
        raise ValueError("sign vector length must be free count + 2")
    if len(omega2_omega5) + 2 < 3:
        raise ValueError("invalid kinematics")

    free = [Fraction(w) for w in omega2_omega5]
    s = sum(free)
    if s == 0:
        raise ZeroDivisionError("sum free frequencies is zero")
    sum_sig = sum(signs[i + 1] * free[i] ** 2 for i in range(len(free)))
    sig0 = Fraction(signs[0])
    wn = -(sig0 * s * s + sum_sig) / (2 * sig0 * s)
    w1 = -(s + wn)
    return (w1, *free, wn)


def momenta_from_omega(omega, signs, g=Fraction(1)):
    return [Fraction(signs[i]) * omega[i] * omega[i] / g for i in range(len(omega))]


# ---------- wall helpers ----------


def wall_key(mask_m, mask_p):
    return "I%02d_J%02d" % (mask_m, mask_p)


def wall_masks_to_expr_diff(mask_m, mask_p):
    terms = []
    for i in subset_bits(mask_m):
        terms.append("a%d" % (i + 1))
    for j in subset_bits(mask_p):
        terms.append("-a%d" % (3 + j + 1))
    if not terms:
        return "0"
    return " + ".join(terms)


def wall_masks_to_expr_sum(mask_m, j_anchor):
    terms = ["a%d" % (i + 1) for i in subset_bits(mask_m)]
    terms.append("a%d" % (3 + j_anchor + 1))
    return "(%s) - T" % (" + ".join(terms))


def _build_diff_walls():
    out = []
    for i in range(3):
        for j in range(3):
            i_mask = 1 << i
            j_mask = 1 << j
            out.append(
                {
                    "kind": "diff",
                    "id": "I%02d_J%02d" % (i_mask, j_mask),
                    "I_mask": i_mask,
                    "J_mask": j_mask,
                    "plus_anchor": j,
                    "q_expression": wall_masks_to_expr_diff(i_mask, j_mask),
                    "subset_sizes": [1, 1],
                    "subset_size_orbit": [1, 1],
                }
            )
    return out


def _build_sum_walls():
    full = 0b111
    out = []
    for i in range(3):
        i_mask = 1 << i
        for j in range(3):
            j_mask = full ^ (1 << j)
            out.append(
                {
                    "kind": "sum",
                    "id": "S_%02d_%02d" % (i_mask, j_mask),
                    "I_mask": i_mask,
                    "J_mask": j_mask,
                    "plus_anchor": j,
                    "q_expression": wall_masks_to_expr_sum(i_mask, j),
                    "subset_sizes": [1, 2],
                    "subset_size_orbit": [1, 2],
                }
            )
    return out


def _build_external_walls():
    out = []
    full = 0b111

    for i in range(3):
        i_mask = 1 << i
        out.append(
            {
                "kind": "boundary",
                "id": "EB_M%02d_P%02d" % (i_mask, full),
                "I_mask": i_mask,
                "J_mask": full,
                "plus_anchor": 0,
                "q_expression": wall_masks_to_expr_diff(i_mask, full),
                "subset_sizes": [1, 3],
                "subset_size_orbit": [1, 3],
            }
        )

    for j in range(3):
        j_mask = 1 << j
        out.append(
            {
                "kind": "boundary",
                "id": "EB_M%02d_P%02d" % (full, j_mask),
                "I_mask": full,
                "J_mask": j_mask,
                "plus_anchor": j,
                "q_expression": wall_masks_to_expr_diff(full, j_mask),
                "subset_sizes": [3, 1],
                "subset_size_orbit": [3, 1],
            }
        )

    return out


def build_wall_catalog():
    nondeg = sorted(_build_diff_walls() + _build_sum_walls(), key=lambda d: d["id"])
    dedup = []
    seen = set()
    for item in nondeg:
        key = item["id"]
        if key in seen:
            continue
        seen.add(key)
        dedup.append(item)
    return dedup


def build_external_wall_catalog():
    return sorted(_build_external_walls(), key=lambda d: d["id"])


def wall_value(a, wall):
    a = [Fraction(x) for x in a]
    I_mask = int(wall.get("I_mask"))
    J_mask = int(wall.get("J_mask"))
    kind = str(wall.get("kind", "diff"))

    sI = sum(a[i] for i in subset_bits(I_mask))
    if kind in ("diff", "boundary"):
        sJ = sum(a[3 + j] for j in subset_bits(J_mask))
        return sI - sJ

    if kind == "sum":
        # external formula: omega_i^2 + omega_{3+j}^2 - (sum of minus squares)
        j = int(wall.get("plus_anchor", 0))
        sM = a[0] + a[1] + a[2]
        return sI + a[3 + j] - sM

    raise ValueError("unknown wall kind")


def wall_sign_map(omega, wall_catalog):
    a = [Fraction(w) * Fraction(w) for w in omega]
    out = {}
    for item in wall_catalog:
        v = wall_value(a, item)
        out[str(item["id"])] = 1 if v > 0 else -1 if v < 0 else 0
    return out


def serialize_signs(sign_map, wall_catalog):
    return "|".join("%s:%s" % (item["id"], sign_map[str(item["id"])]) for item in wall_catalog)


def sort_partition_idx(omega, idxs):
    return sorted(list(idxs), key=lambda i: (omega[i] * omega[i], omega[i]))


def local_omega_from_perm(omega, minus_idx, plus_idx, perm_m, perm_p, swap):
    if swap:
        return tuple(omega[plus_idx[perm_m[i]]] for i in range(3)) + tuple(
            omega[minus_idx[perm_p[i]]] for i in range(3)
        )
    return tuple(omega[minus_idx[perm_m[i]]] for i in range(3)) + tuple(
        omega[plus_idx[perm_p[i]]] for i in range(3)
    )


def canonicalize_wall_signatures(omega, wall_catalog, minus_idx, plus_idx, allow_swap=True):
    perms = [tuple(p) for p in permutations(range(3))]
    swaps = (False, True) if allow_swap else (False,)
    full = list(omega)
    best = None

    for do_swap in swaps:
        for perm_m in perms:
            for perm_p in perms:
                local = local_omega_from_perm(full, minus_idx, plus_idx, perm_m, perm_p, do_swap)
                s = wall_sign_map(local, wall_catalog)
                key = serialize_signs(s, wall_catalog)
                if best is None or key < best[0]:
                    best = (key, s)

    if best is None:
        raise RuntimeError("cannot canonicalize wall signatures")

